/* ============================================
   ShiftWise — Restaurant Team Management SaaS
   Global Stylesheet
   ============================================ */

/* CSS Variables */
:root {
  --primary: #0051C3;
  --primary-dark: #003d94;
  --accent: #DE5052;
  --accent-dark: #c23e40;
  --white: #FFFFFF;
  --gray-50: #F8FAFC;
  --gray-100: #F1F5F9;
  --gray-200: #E2E8F0;
  --gray-300: #CBD5E1;
  --gray-400: #94A3B8;
  --gray-500: #64748B;
  --gray-600: #475569;
  --gray-700: #334155;
  --gray-800: #1E293B;
  --gray-900: #0F172A;
  --success: #10B981;
  --font-heading: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --shadow-sm: 0 1px 2px 0 rgb(0 0 0 / 0.05);
  --shadow-md: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
  --shadow-lg: 0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.1);
  --shadow-xl: 0 20px 25px -5px rgb(0 0 0 / 0.1), 0 8px 10px -6px rgb(0 0 0 / 0.1);
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --max-width: 1200px;
  --transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);
}

/* Reset & Base */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  color: var(--gray-700);
  background: var(--white);
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

ul, ol {
  list-style: none;
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 700;
  line-height: 1.2;
  color: var(--gray-900);
  letter-spacing: -0.02em;
}

h1 { font-size: clamp(2.5rem, 5vw, 3.5rem); }
h2 { font-size: clamp(1.75rem, 3.5vw, 2.5rem); }
h3 { font-size: clamp(1.25rem, 2.5vw, 1.5rem); }
h4 { font-size: 1.125rem; }

p {
  color: var(--gray-600);
}

/* Layout Utilities */
.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 1.5rem;
}

.section {
  padding: 5rem 0;
}

.section-alt {
  background: var(--gray-50);
}

.text-center {
  text-align: center;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.875rem 1.75rem;
  font-size: 0.9375rem;
  font-weight: 600;
  border-radius: var(--radius-md);
  transition: var(--transition);
  white-space: nowrap;
}

.btn-primary {
  background: var(--primary);
  color: var(--white);
  box-shadow: 0 4px 14px rgba(0, 81, 195, 0.3);
}

.btn-primary:hover {
  background: var(--primary-dark);
  transform: translateY(-1px);
  box-shadow: 0 6px 20px rgba(0, 81, 195, 0.35);
}

.btn-accent {
  background: var(--accent);
  color: var(--white);
  box-shadow: 0 4px 14px rgba(222, 80, 82, 0.3);
}

.btn-accent:hover {
  background: var(--accent-dark);
  transform: translateY(-1px);
  box-shadow: 0 6px 20px rgba(222, 80, 82, 0.35);
}

.btn-outline {
  background: transparent;
  color: var(--gray-700);
  border: 2px solid var(--gray-300);
}

.btn-outline:hover {
  border-color: var(--primary);
  color: var(--primary);
  background: rgba(0, 81, 195, 0.04);
}

.btn-white {
  background: var(--white);
  color: var(--primary);
  box-shadow: var(--shadow-md);
}

.btn-white:hover {
  transform: translateY(-1px);
  box-shadow: var(--shadow-lg);
}

.btn-lg {
  padding: 1rem 2.25rem;
  font-size: 1rem;
}

/* Header */
.header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255, 255, 255, 0.92);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--gray-200);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.logo {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--gray-900);
  letter-spacing: -0.03em;
}

.logo-icon {
  width: 36px;
  height: 36px;
  background: var(--primary);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  font-size: 1.25rem;
}

.logo span {
  color: var(--accent);
}

.nav-desktop {
  display: none;
}

.nav-desktop a {
  padding: 0.5rem 1rem;
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--gray-600);
  transition: var(--transition);
  border-radius: var(--radius-sm);
}

.nav-desktop a:hover,
.nav-desktop a.active {
  color: var(--primary);
  background: rgba(0, 81, 195, 0.06);
}

.header-cta {
  display: none;
}

.mobile-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  border-radius: var(--radius-sm);
  color: var(--gray-700);
  font-size: 1.5rem;
  transition: var(--transition);
}

.mobile-toggle:hover {
  background: var(--gray-100);
}

/* Mobile Navigation */
.mobile-nav {
  position: fixed;
  inset: 0;
  z-index: 200;
  background: rgba(15, 23, 42, 0.4);
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.3s, visibility 0.3s;
}

.mobile-nav.open {
  opacity: 1;
  visibility: visible;
}

.mobile-nav-panel {
  position: absolute;
  top: 0;
  right: 0;
  width: min(320px, 85vw);
  height: 100%;
  background: var(--white);
  box-shadow: var(--shadow-xl);
  transform: translateX(100%);
  transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  display: flex;
  flex-direction: column;
  padding: 1.5rem;
}

.mobile-nav.open .mobile-nav-panel {
  transform: translateX(0);
}

.mobile-nav-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 2rem;
}

.mobile-nav-close {
  width: 40px;
  height: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-sm);
  color: var(--gray-500);
  font-size: 1.5rem;
  transition: var(--transition);
}

.mobile-nav-close:hover {
  background: var(--gray-100);
  color: var(--gray-700);
}

.mobile-nav-links {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  flex: 1;
}

.mobile-nav-links a {
  padding: 0.875rem 1rem;
  font-size: 1.0625rem;
  font-weight: 500;
  color: var(--gray-700);
  border-radius: var(--radius-sm);
  transition: var(--transition);
}

.mobile-nav-links a:hover,
.mobile-nav-links a.active {
  background: var(--gray-100);
  color: var(--primary);
}

.mobile-nav-cta {
  margin-top: 1.5rem;
  padding-top: 1.5rem;
  border-top: 1px solid var(--gray-200);
}

.mobile-nav-cta .btn {
  width: 100%;
}

/* Hero */
.hero {
  position: relative;
  padding: 4rem 0 5rem;
  overflow: hidden;
}

.hero-bg {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, var(--gray-50) 0%, #EEF4FF 50%, var(--gray-50) 100%);
  z-index: -2;
}

.hero-pattern {
  position: absolute;
  inset: 0;
  background-image: radial-gradient(circle at 1px 1px, var(--gray-300) 1px, transparent 0);
  background-size: 40px 40px;
  opacity: 0.4;
  z-index: -1;
}

.hero-inner {
  display: grid;
  gap: 3rem;
  align-items: center;
}

.hero-content {
  max-width: 600px;
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.375rem 1rem;
  background: rgba(0, 81, 195, 0.08);
  color: var(--primary);
  font-size: 0.875rem;
  font-weight: 600;
  border-radius: 100px;
  margin-bottom: 1.5rem;
}

.hero-title {
  margin-bottom: 1.25rem;
  line-height: 1.1;
}

.hero-title span {
  color: var(--primary);
}

.hero-subtitle {
  font-size: clamp(1.0625rem, 2vw, 1.25rem);
  color: var(--gray-500);
  margin-bottom: 2rem;
  line-height: 1.7;
}

.hero-buttons {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
}

.hero-visual {
  position: relative;
}

.hero-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-xl);
  padding: 1.5rem;
  border: 1px solid var(--gray-200);
}

.hero-card-header {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  margin-bottom: 1rem;
  padding-bottom: 1rem;
  border-bottom: 1px solid var(--gray-100);
}

.hero-card-avatar {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--primary), var(--accent));
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  font-weight: 700;
  font-size: 0.875rem;
}

.hero-card-meta h4 {
  font-size: 0.9375rem;
  color: var(--gray-900);
}

.hero-card-meta p {
  font-size: 0.8125rem;
  color: var(--gray-400);
}

.schedule-grid {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 0.375rem;
}

.schedule-day {
  text-align: center;
  padding: 0.5rem 0.25rem;
  border-radius: var(--radius-sm);
  font-size: 0.75rem;
}

.schedule-day-label {
  color: var(--gray-400);
  font-weight: 600;
  margin-bottom: 0.25rem;
  font-size: 0.6875rem;
  text-transform: uppercase;
}

.schedule-day-shift {
  background: var(--primary);
  color: var(--white);
  border-radius: 4px;
  padding: 0.25rem;
  font-size: 0.6875rem;
  font-weight: 600;
}

.schedule-day-shift.alt {
  background: var(--accent);
}

.schedule-day-shift.off {
  background: var(--gray-100);
  color: var(--gray-400);
}

/* Section Header */
.section-header {
  max-width: 640px;
  margin: 0 auto 3.5rem;
}

.section-header h2 {
  margin-bottom: 1rem;
}

.section-header h2 span {
  color: var(--primary);
}

.section-header p {
  font-size: 1.0625rem;
  color: var(--gray-500);
}

/* Feature Cards */
.features-grid {
  display: grid;
  gap: 1.5rem;
}

.feature-card {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  padding: 2rem;
  transition: var(--transition);
}

.feature-card:hover {
  border-color: var(--gray-300);
  box-shadow: var(--shadow-lg);
  transform: translateY(-3px);
}

.feature-icon {
  width: 52px;
  height: 52px;
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  margin-bottom: 1.25rem;
}

.feature-icon.blue {
  background: rgba(0, 81, 195, 0.08);
  color: var(--primary);
}

.feature-icon.red {
  background: rgba(222, 80, 82, 0.08);
  color: var(--accent);
}

.feature-icon.green {
  background: rgba(16, 185, 129, 0.08);
  color: var(--success);
}

.feature-icon.purple {
  background: rgba(139, 92, 246, 0.08);
  color: #8B5CF6;
}

.feature-icon.orange {
  background: rgba(249, 115, 22, 0.08);
  color: #F97316;
}

.feature-card h3 {
  margin-bottom: 0.625rem;
  font-size: 1.125rem;
}

.feature-card p {
  font-size: 0.9375rem;
  line-height: 1.65;
}

/* How It Works */
.steps-grid {
  display: grid;
  gap: 2rem;
}

.step {
  display: flex;
  gap: 1.25rem;
  align-items: flex-start;
}

.step-number {
  flex-shrink: 0;
  width: 48px;
  height: 48px;
  border-radius: var(--radius-md);
  background: var(--primary);
  color: var(--white);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  font-weight: 700;
}

.step-content h3 {
  margin-bottom: 0.5rem;
  font-size: 1.125rem;
}

.step-content p {
  font-size: 0.9375rem;
  color: var(--gray-500);
  line-height: 1.65;
}

/* Testimonials */
.testimonials-section {
  background: linear-gradient(180deg, var(--gray-50) 0%, var(--white) 100%);
}

.testimonial-carousel {
  position: relative;
  max-width: 800px;
  margin: 0 auto;
}

.testimonial-card {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  padding: 2.5rem;
  box-shadow: var(--shadow-md);
  text-align: center;
  transition: opacity 0.4s, transform 0.4s;
}

.testimonial-quote {
  font-size: 1.25rem;
  color: var(--gray-700);
  line-height: 1.7;
  margin-bottom: 1.5rem;
  font-style: italic;
}

.testimonial-author {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.25rem;
}

.testimonial-avatar {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--primary), var(--accent));
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  font-weight: 700;
  font-size: 1.125rem;
  margin-bottom: 0.75rem;
}

.testimonial-name {
  font-weight: 700;
  color: var(--gray-900);
  font-size: 1rem;
}

.testimonial-role {
  font-size: 0.875rem;
  color: var(--gray-400);
}

.testimonial-nav {
  display: flex;
  justify-content: center;
  gap: 1rem;
  margin-top: 2rem;
}

.testimonial-nav button {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  border: 2px solid var(--gray-200);
  color: var(--gray-500);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  transition: var(--transition);
}

.testimonial-nav button:hover {
  border-color: var(--primary);
  color: var(--primary);
  background: rgba(0, 81, 195, 0.04);
}

.testimonial-dots {
  display: flex;
  justify-content: center;
  gap: 0.5rem;
  margin-top: 1.25rem;
}

.testimonial-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--gray-300);
  transition: var(--transition);
}

.testimonial-dot.active {
  background: var(--primary);
  width: 24px;
  border-radius: 4px;
}

/* Stats */
.stats-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 2rem;
}

.stat-item {
  text-align: center;
}

.stat-value {
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 800;
  color: var(--primary);
  line-height: 1;
  margin-bottom: 0.5rem;
  letter-spacing: -0.03em;
}

.stat-label {
  font-size: 0.9375rem;
  color: var(--gray-500);
  font-weight: 500;
}

/* Pricing */
.pricing-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  margin-bottom: 3rem;
}

.pricing-toggle-label {
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--gray-500);
  transition: var(--transition);
}

.pricing-toggle-label.active {
  color: var(--gray-900);
}

.toggle-switch {
  position: relative;
  width: 52px;
  height: 28px;
  background: var(--gray-300);
  border-radius: 100px;
  cursor: pointer;
  transition: var(--transition);
}

.toggle-switch.active {
  background: var(--primary);
}

.toggle-switch::after {
  content: '';
  position: absolute;
  top: 3px;
  left: 3px;
  width: 22px;
  height: 22px;
  background: var(--white);
  border-radius: 50%;
  transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  box-shadow: var(--shadow-sm);
}

.toggle-switch.active::after {
  transform: translateX(24px);
}

.pricing-grid {
  display: grid;
  gap: 1.5rem;
  max-width: 1000px;
  margin: 0 auto;
}

.pricing-card {
  background: var(--white);
  border: 2px solid var(--gray-200);
  border-radius: var(--radius-lg);
  padding: 2.5rem 2rem;
  transition: var(--transition);
  position: relative;
}

.pricing-card:hover {
  border-color: var(--gray-300);
  box-shadow: var(--shadow-lg);
}

.pricing-card.featured {
  border-color: var(--primary);
  box-shadow: 0 0 0 4px rgba(0, 81, 195, 0.08), var(--shadow-lg);
}

.pricing-card.featured::before {
  content: 'Most Popular';
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--primary);
  color: var(--white);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  padding: 0.375rem 1rem;
  border-radius: 100px;
}

.pricing-name {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--gray-900);
  margin-bottom: 0.5rem;
}

.pricing-desc {
  font-size: 0.875rem;
  color: var(--gray-400);
  margin-bottom: 1.5rem;
}

.pricing-price {
  display: flex;
  align-items: baseline;
  gap: 0.25rem;
  margin-bottom: 1.5rem;
}

.pricing-price .currency {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--gray-900);
}

.pricing-price .amount {
  font-size: 3rem;
  font-weight: 800;
  color: var(--gray-900);
  line-height: 1;
  letter-spacing: -0.03em;
}

.pricing-price .period {
  font-size: 0.9375rem;
  color: var(--gray-400);
  font-weight: 500;
}

.pricing-features {
  display: flex;
  flex-direction: column;
  gap: 0.875rem;
  margin-bottom: 2rem;
}

.pricing-feature {
  display: flex;
  align-items: center;
  gap: 0.625rem;
  font-size: 0.9375rem;
  color: var(--gray-600);
}

.pricing-feature i {
  font-size: 1.125rem;
  flex-shrink: 0;
}

.pricing-feature i.ri-check-line {
  color: var(--success);
}

.pricing-feature i.ri-close-line {
  color: var(--gray-300);
}

.pricing-card .btn {
  width: 100%;
}

/* Pricing Table (detailed) */
.pricing-table-section {
  overflow-x: auto;
}

.pricing-table {
  width: 100%;
  min-width: 700px;
  border-collapse: collapse;
  font-size: 0.9375rem;
}

.pricing-table th,
.pricing-table td {
  padding: 1rem 1.25rem;
  text-align: left;
  border-bottom: 1px solid var(--gray-200);
}

.pricing-table th {
  font-weight: 700;
  color: var(--gray-900);
  background: var(--gray-50);
}

.pricing-table th:first-child {
  border-radius: var(--radius-sm) 0 0 0;
}

.pricing-table th:last-child {
  border-radius: 0 var(--radius-sm) 0 0;
}

.pricing-table td {
  color: var(--gray-600);
}

.pricing-table tr:last-child td:first-child {
  border-radius: 0 0 0 var(--radius-sm);
}

.pricing-table tr:last-child td:last-child {
  border-radius: 0 0 var(--radius-sm) 0;
}

.pricing-table tr:hover td {
  background: var(--gray-50);
}

/* FAQ */
.faq-list {
  max-width: 720px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.faq-item {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: var(--transition);
}

.faq-item:hover {
  border-color: var(--gray-300);
}

.faq-item.active {
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(0, 81, 195, 0.06);
}

.faq-question {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 1.25rem 1.5rem;
  font-size: 1rem;
  font-weight: 600;
  color: var(--gray-900);
